-- Two words of the Varalakshmi Vayana Dhanam mantra, corrected against book
-- p.137. Generated by scripts/build-vayana-dhanam-repair.mjs; see its header.

begin;

update public.pooja_steps set
  mantra_sanskrit = replace(replace(mantra_sanskrit, 'सादुगुण्यं', 'साद्गुण्यं'), 'सौमाङ्गल्यावािं', 'सौमाङ्गल्यावाप्तिं'),
  mantra_tamil = replace(replace(mantra_tamil, 'ஸாதுகுண்யம்', 'ஸாத்குண்யம்'), 'ஸௌமாங்கல்யாவாிம்', 'ஸௌமாங்கல்யாவாப்திம்'),
  mantra_translit = replace(replace(mantra_translit, 'sāduguṇyaṃ', 'sādguṇyaṃ'), 'saumāṅgalyāvāiṃ', 'saumāṅgalyāvāptiṃ'),
  updated_at = now()
 where pooja_id = 'varalakshmi_vratham' and step_title_en = 'Vayana Dhanam'
   and (position('सादुगुण्यं' in mantra_sanskrit) > 0
        or position('सौमाङ्गल्यावािं' in mantra_sanskrit) > 0
        or position('ஸாதுகுண்யம்' in mantra_tamil) > 0
        or position('ஸௌமாங்கல்யாவாிம்' in mantra_tamil) > 0
        or position('sāduguṇyaṃ' in mantra_translit) > 0
        or position('saumāṅgalyāvāiṃ' in mantra_translit) > 0);

-- Afterwards no column may still carry a slip, and every column must carry the
-- correction. Re-runnable: on a second run the update matches nothing and these
-- still hold.
do $$
declare n int;
begin
  select count(*) into n from public.pooja_steps
   where pooja_id = 'varalakshmi_vratham' and step_title_en = 'Vayana Dhanam'
     and position('साद्गुण्यं' in mantra_sanskrit) > 0
     and position('सौमाङ्गल्यावाप्तिं' in mantra_sanskrit) > 0
     and position('ஸாத்குண்யம்' in mantra_tamil) > 0
     and position('ஸௌமாங்கல்யாவாப்திம்' in mantra_tamil) > 0
     and position('sādguṇyaṃ' in mantra_translit) > 0
     and position('saumāṅgalyāvāptiṃ' in mantra_translit) > 0;
  if n <> 1 then raise exception 'Vayana Dhanam: a correction is missing from one of the three scripts'; end if;
  select count(*) into n from public.pooja_steps
   where pooja_id = 'varalakshmi_vratham' and step_title_en = 'Vayana Dhanam'
     and (position('सादुगुण्यं' in mantra_sanskrit) > 0
          or position('सौमाङ्गल्यावािं' in mantra_sanskrit) > 0
          or position('ஸாதுகுண்யம்' in mantra_tamil) > 0
          or position('ஸௌமாங்கல்யாவாிம்' in mantra_tamil) > 0
          or position('sāduguṇyaṃ' in mantra_translit) > 0
          or position('saumāṅgalyāvāiṃ' in mantra_translit) > 0);
  if n <> 0 then raise exception 'Vayana Dhanam: a slip survived'; end if;
end $$;


-- Carriage returns, from pasting this file into a browser SQL editor. See
-- scripts/_migration.mjs.
do $$
declare
  r record;
  n bigint;
begin
  for r in
    select c.table_name, c.column_name
      from information_schema.columns c
      join information_schema.tables t
        on t.table_schema = c.table_schema and t.table_name = c.table_name
     where c.table_schema = 'public'
       and t.table_type = 'BASE TABLE'
       and c.data_type in ('text', 'character varying', 'character')
  loop
    execute format(
      'update public.%I set %I = replace(%I, chr(13), %L)'
      || ' where position(chr(13) in %I) > 0',
      r.table_name, r.column_name, r.column_name, '', r.column_name
    );
    get diagnostics n = row_count;
    if n > 0 then
      raise notice 'stripped CR from % row(s) of %.%', n, r.table_name, r.column_name;
    end if;
  end loop;
end $$;

commit;
